import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);int t = Integer.parseInt(br.readLine());long MOD = 998244353;long[] fact = new long[200005];fact[0] = 1;for (int i = 1; i < 200005; i++) fact[i] = (fact[i - 1] * i) % MOD;while (t-- > 0) {String s = br.readLine();int n = s.length();int ops = 0;long ways = 1;int i = 0;while (i < n) {int j = i;while (j < n && s.charAt(j) == s.charAt(i)) j++;int len = j - i;if (len > 1) {ops += (len - 1);ways = (ways * len) % MOD;}i = j;}ways = (ways * fact[ops]) % MOD;out.println(ops + " " + ways);}out.flush();out.close();}}